/**
 * Contract between the DataTable and the eduardoapatat/laravel-inertia-datatable package.
 *
 * Plain TypeScript, without React, Vue or Inertia dependencies: types of the
 * server response and conversion of the table state to a query string.
 * See docs/contract.md in the package.
 */

import { normalizeRelativeDate } from '@/lib/data-table-relative-date';

export type FilterVariant =
    | 'text'
    | 'number'
    | 'range'
    | 'date'
    | 'date-range'
    | 'boolean'
    | 'select'
    | 'multi-select';

export type FilterOperator =
    | 'iLike'
    | 'notILike'
    | 'eq'
    | 'ne'
    | 'inArray'
    | 'notInArray'
    | 'isEmpty'
    | 'isNotEmpty'
    | 'lt'
    | 'lte'
    | 'gt'
    | 'gte'
    | 'isBetween'
    | 'isRelativeToToday';

/**
 * How the column filters are combined: all of them (`and`, the default) or
 * any of them (`or`, the `join=or` parameter).
 */
export type JoinOperator = 'and' | 'or';

export interface ServerSort {
    id: string;
    desc: boolean;
}

export interface ServerFilter {
    id: string;
    filterId?: string;
    variant: FilterVariant;
    operator: FilterOperator;
    value: string | string[];
    /**
     * Of a `rel` filter (`isRelativeToToday`): the first and last day the
     * server resolved its token to (`YYYY-MM-DD`).
     */
    range?: [string, string];
}

/**
 * How the currency of `->money()` is shown: the symbol before the number
 * (`$1.234`, by default), the code after it (`1.234 CLP`), both
 * (`$1.234 CLP`) or nothing (`1.234`).
 */
export type CurrencyDisplay = 'symbol' | 'code' | 'both' | 'none';

/**
 * How the cells of a column are displayed; `type` is the type of the column
 * (`Column::number()`, `Column::date()`…). Formats are Intl options, applied on
 * the client with the table locale.
 */
export type ServerColumnDisplay = (
    | {
          type: 'number';
          format?: Intl.NumberFormatOptions;
          /** Unit after plain numbers (`->unit('kg')`). */
          unit?: string;
          /**
           * Where the unit is hidden: in the cells (and the filter label) or
           * next to the filter inputs; shown when missing.
           */
          showUnit?: { cell?: false; filter?: false };
          /**
           * Currency of `->money()` in the cells (and the filter label) and
           * next to the filter inputs; `symbol` when missing.
           */
          currency?: { cell?: CurrencyDisplay; filter?: CurrencyDisplay };
      }
    | {
          type: 'date';
          /** Without it, the date format of the table. */
          format?:
              | 'short'
              | 'medium'
              | 'long'
              | 'datetime'
              | 'relative'
              | Intl.DateTimeFormatOptions;
      }
    | { type: 'text'; limit?: number; link?: 'url' | 'email' }
    | {
          type: 'boolean';
          labels?: { true: string; false: string };
          /** Labels with the project's shadcn Badge. */
          badge?: boolean;
          /** Badge variant of the column (`outline` by default). */
          variant?: string;
          /** Badge variant of `true` and `false`. */
          variants?: { true?: string; false?: string };
      }
    | {
          type: 'option';
          /** Labels with the project's shadcn Badge. */
          badge?: boolean;
          /** Badge variant of the column (`outline` by default). */
          variant?: string;
          /** Badge variant per option value. */
          variants?: Record<string, string>;
          /**
           * In a column with several values (`multiple`), how many the cell
           * shows before a "+N" with the rest (`->maxVisible()`); 3 when missing.
           */
          max?: number;
      }
) & {
    /**
     * Text of the cells without a value (`->whenEmpty()`); without it, the
     * `empty` message (`—`).
     */
    empty?: string;
};

/** Filter of a column (`->filterInput()`, `->filterSelect()`, `->filterRange()`…). */
export interface ServerColumnFilter {
    variant: FilterVariant;
    placeholder?: string;
    /**
     * The date filter offers days relative to today next to the calendar
     * (`presets: true`), sent as `rel`.
     */
    presets?: true;
    /** The filter also offers the rows without a value (`empty: true`). */
    empty?: true;
}

export interface ServerColumnConfig {
    id: string;
    label: string;
    sortable: boolean;
    hideable: boolean;
    visible: boolean;
    display: ServerColumnDisplay;
    /** Null: the column has no filter. */
    filter: ServerColumnFilter | null;
    /**
     * The value of each row is a list (a to-many relation): the filters match
     * when some value does, and the negations when none does.
     */
    multiple?: true;
}

export interface ServerFacetOption {
    /** `null`: the rows without a value, last, with `empty: true`. */
    value: string | null;
    label: string;
    count?: number;
}

export interface ServerRangeFacet {
    min: number | null;
    max: number | null;
}

export interface ServerQueryKeys {
    page: string;
    per_page: string;
    sort: string;
    filter: string;
    search: string;
    columns: string;
    /** Missing in packages before `join=or`. */
    join?: string;
}

export interface ServerTableConfig {
    columns: ServerColumnConfig[];
    searchable: boolean;
    /** Locale to format numbers and dates (table, config or app); null uses the browser's. */
    locale?: string | null;
    /** Preset of the date columns without their own format. */
    date_format?: 'short' | 'medium' | 'long' | 'datetime' | 'relative';
    /** UI texts in the app language (lang/vendor/inertia-datatable). */
    messages?: Record<string, string>;
    per_page: number;
    per_page_options: number[];
    default_sorting: ServerSort[];
    /** Most columns the server sorts by (`inertia-datatable.max_sorts`). */
    max_sorts?: number;
    /** Most filters the server applies (`inertia-datatable.max_filters`). */
    max_filters?: number;
    query: ServerQueryKeys;
}

export interface ServerTableState {
    pagination: { pageIndex: number; pageSize: number };
    sorting: ServerSort[];
    columnFilters: ServerFilter[];
    /** Missing in packages before `join=or`, which is `and`. */
    join?: JoinOperator;
    globalFilter: string;
    columnVisibility: Record<string, boolean>;
}

/**
 * Package response: the Inertia prop (or the JSON) of a table.
 */
export interface ServerDataTable<TData> {
    data: TData[];
    meta: {
        current_page: number;
        per_page: number;
        last_page: number;
        total: number;
        from: number | null;
        to: number | null;
    };
    state: ServerTableState;
    facets: Record<string, ServerFacetOption[] | ServerRangeFacet>;
    config: ServerTableConfig;
}

/**
 * Table state to put in the URL.
 */
export interface TableQueryState {
    pageIndex: number;
    pageSize: number;
    sorting: ServerSort[];
    filters: ServerFilter[];
    /** `and` when missing. */
    join?: JoinOperator;
    globalFilter: string;
    columnVisibility: Record<string, boolean>;
}

export const FILTER_OPERATOR_URL_NAMES = {
    iLike: 'ilike',
    notILike: 'not.ilike',
    eq: 'eq',
    ne: 'neq',
    inArray: 'in',
    notInArray: 'not.in',
    isEmpty: 'is.empty',
    isNotEmpty: 'not.is.empty',
    lt: 'lt',
    lte: 'lte',
    gt: 'gt',
    gte: 'gte',
    isBetween: 'between',
    isRelativeToToday: 'rel',
} as const satisfies Record<FilterOperator, string>;

/**
 * Operator of each variant that the URL leaves out (`filter[name]=ana` is
 * `ilike`): the one of the plain value a filter component writes.
 */
export const IMPLICIT_OPERATORS: Record<FilterVariant, FilterOperator> = {
    text: 'iLike',
    number: 'eq',
    range: 'isBetween',
    date: 'eq',
    'date-range': 'isBetween',
    boolean: 'eq',
    select: 'inArray',
    'multi-select': 'inArray',
};

const LIST_OPERATORS = new Set<FilterOperator>([
    'inArray',
    'notInArray',
    'isBetween',
]);

const VALUELESS_OPERATORS = new Set<FilterOperator>(['isEmpty', 'isNotEmpty']);

/**
 * Names the server accepts as an operator (URL form and key).
 */
const OPERATOR_NAMES = Object.entries(FILTER_OPERATOR_URL_NAMES).flatMap(
    ([key, urlName]) => [key.toLowerCase(), urlName],
);

/**
 * `[{ id: 'created_at', desc: true }, { id: 'name', desc: false }]` → `-created_at,name`.
 */
export function serializeSorting(sorting: ServerSort[]): string {
    return sorting
        .map((sort) => (sort.desc ? `-${sort.id}` : sort.id))
        .join(',');
}

/**
 * Value of `filter[<col>]` with the `[<operator>.]<value>` syntax.
 * Returns `null` when the filter has no value (it must not go in the URL).
 */
export function serializeFilter(filter: ServerFilter): string | null {
    const urlName = FILTER_OPERATOR_URL_NAMES[filter.operator];

    if (VALUELESS_OPERATORS.has(filter.operator)) {
        return urlName;
    }

    if (filter.operator === 'isRelativeToToday') {
        const single = Array.isArray(filter.value)
            ? (filter.value[0] ?? '')
            : filter.value;
        const token = normalizeRelativeDate(single);

        return token === null ? null : `${urlName}.${token}`;
    }

    const raw = LIST_OPERATORS.has(filter.operator)
        ? serializeList(filter)
        : serializeSingle(filter.value);

    if (raw === null) {
        return null;
    }

    const isImplicit = filter.operator === IMPLICIT_OPERATORS[filter.variant];

    return isImplicit && !startsWithOperatorName(raw)
        ? raw
        : `${urlName}.${raw}`;
}

/**
 * Query string `[key, value]` pairs for the given state. Leaves out whatever
 * matches the default so URLs stay clean.
 */
export function stateToQuery(
    state: TableQueryState,
    config: ServerTableConfig,
): Array<[string, string]> {
    const keys = config.query;
    const pairs: Array<[string, string]> = [];

    if (state.pageIndex > 0) {
        pairs.push([keys.page, String(state.pageIndex + 1)]);
    }

    if (state.pageSize !== config.per_page) {
        pairs.push([keys.per_page, String(state.pageSize)]);
    }

    if (state.sorting.length > 0) {
        pairs.push([keys.sort, serializeSorting(state.sorting)]);
    }

    pairs.push(...filterPairs(state.filters, keys.filter));

    // Servers without `keys.join` do not support it.
    if (state.join === 'or' && keys.join !== undefined) {
        pairs.push([keys.join, 'or']);
    }

    const search = state.globalFilter.trim();

    if (search !== '') {
        pairs.push([keys.search, search]);
    }

    const visible = visibleColumns(state.columnVisibility, config.columns);
    const defaults = config.columns
        .filter((column) => column.visible)
        .map((column) => column.id);

    if (visible.join(',') !== defaults.join(',')) {
        pairs.push([keys.columns, visible.join(',')]);
    }

    return pairs;
}

/**
 * URL with the table state, keeping the parameters that are not its own
 * (other tables on the page, the screen's own filters…).
 */
export function buildTableUrl(
    href: string,
    pairs: Array<[string, string]>,
    keys: ServerQueryKeys,
): string {
    const url = new URL(href);
    const kept = [...url.searchParams.entries()].filter(
        ([key]) => !isTableQueryKey(key, keys),
    );
    const query = [...kept, ...pairs]
        .map(([key, value]) => `${encodeKey(key)}=${encodeValue(value)}`)
        .join('&');

    return `${url.pathname}${query === '' ? '' : `?${query}`}${url.hash}`;
}

export interface ArrangeColumnsOptions<T> {
    /** Id of the client column, if it has one. */
    getId: (column: T) => string | undefined;
    /** Client-only columns that go first (e.g. the selection column). */
    isLeading: (column: T) => boolean;
    /** Final column for a server id; receives the client one if it exists. */
    resolve: (id: string, column: T | undefined) => T;
}

/**
 * The table class decides which columns exist and in which order: every server
 * column appears in its order, using the client column with the same id if it
 * exists. Client-only columns go at the end, except the ones marked as leading.
 */
export function arrangeColumns<T>(
    clientColumns: readonly T[],
    serverIds: readonly string[],
    { getId, isLeading, resolve }: ArrangeColumnsOptions<T>,
): T[] {
    const server = new Set(serverIds);
    const byId = new Map<string, T>();
    const leading: T[] = [];
    const trailing: T[] = [];

    for (const column of clientColumns) {
        const id = getId(column);

        if (id !== undefined && server.has(id)) {
            byId.set(id, column);
        } else if (isLeading(column)) {
            leading.push(column);
        } else {
            trailing.push(column);
        }
    }

    return [
        ...leading,
        ...serverIds.map((id) => resolve(id, byId.get(id))),
        ...trailing,
    ];
}

export function isTableQueryKey(key: string, keys: ServerQueryKeys): boolean {
    return (
        key === keys.page ||
        key === keys.per_page ||
        key === keys.sort ||
        key === keys.search ||
        key === keys.columns ||
        (keys.join !== undefined && key === keys.join) ||
        key === keys.filter ||
        key.startsWith(`${keys.filter}[`)
    );
}

function filterPairs(
    filters: ServerFilter[],
    filterKey: string,
): Array<[string, string]> {
    const byColumn = new Map<string, string[]>();

    for (const filter of filters) {
        const value = serializeFilter(filter);

        if (value === null) {
            continue;
        }

        byColumn.set(filter.id, [...(byColumn.get(filter.id) ?? []), value]);
    }

    return [...byColumn.entries()].flatMap(([id, values]) =>
        values.length === 1
            ? [[`${filterKey}[${id}]`, values[0] ?? ''] as [string, string]]
            : values.map(
                  (value) =>
                      [`${filterKey}[${id}][]`, value] as [string, string],
              ),
    );
}

function visibleColumns(
    visibility: Record<string, boolean>,
    columns: ServerColumnConfig[],
): string[] {
    return columns
        .filter(
            (column) =>
                !column.hideable || (visibility[column.id] ?? column.visible),
        )
        .map((column) => column.id);
}

function serializeList(filter: ServerFilter): string | null {
    const values = Array.isArray(filter.value) ? filter.value : [filter.value];

    if (filter.operator === 'isBetween') {
        const [from = '', to = ''] = values;

        return from === '' && to === '' ? null : joinList([from, to]);
    }

    const present = values.filter((value) => value !== '');

    return present.length === 0 ? null : joinList(present);
}

function serializeSingle(value: string | string[]): string | null {
    const single = Array.isArray(value) ? (value[0] ?? '') : value;

    return single.trim() === '' ? null : single;
}

/**
 * Comma-separated list; values with commas, quotes or surrounding spaces are
 * quoted, doubling the inner quotes.
 */
function joinList(values: string[]): string {
    return values
        .map((value) =>
            /[,"]/.test(value) || value !== value.trim()
                ? `"${value.replaceAll('"', '""')}"`
                : value,
        )
        .join(',');
}

function startsWithOperatorName(raw: string): boolean {
    const lower = raw.toLowerCase();

    return OPERATOR_NAMES.some(
        (name) => lower === name || lower.startsWith(`${name}.`),
    );
}

/**
 * Brackets and commas are kept readable: they are valid in a query string.
 */
function encodeKey(key: string): string {
    return encodeURIComponent(key)
        .replaceAll('%5B', '[')
        .replaceAll('%5D', ']');
}

function encodeValue(value: string): string {
    return encodeURIComponent(value).replaceAll('%2C', ',');
}

import type { DataTableMessageKey } from '@/lib/data-table-messages';

/**
 * Tokens of the `rel` operator (`filter[published_at]=rel.-7d`): days relative
 * to today that the server resolves on each request (docs/contract.md §1.4).
 * The client never turns them into dates: it shows their label and the `range`
 * the server answered with.
 */

/** Tokens offered by the filter list and the date filter with `presets`. */
export const RELATIVE_DATE_PRESETS = [
    'today',
    'yesterday',
    '-7d',
    '-30d',
    'this-week',
    'last-week',
    'this-month',
    'last-month',
    'this-quarter',
    'this-year',
    'last-year',
] as const;

const DAY_MESSAGES: Record<string, DataTableMessageKey> = {
    today: 'relative_today',
    yesterday: 'relative_yesterday',
    tomorrow: 'relative_tomorrow',
};

const PERIOD_MESSAGES: Record<string, DataTableMessageKey> = {
    'this-week': 'relative_this_week',
    'last-week': 'relative_last_week',
    'next-week': 'relative_next_week',
    'this-month': 'relative_this_month',
    'last-month': 'relative_last_month',
    'next-month': 'relative_next_month',
    'this-quarter': 'relative_this_quarter',
    'last-quarter': 'relative_last_quarter',
    'next-quarter': 'relative_next_quarter',
    'this-year': 'relative_this_year',
    'last-year': 'relative_last_year',
    'next-year': 'relative_next_year',
};

/** Largest N of each unit (about ten years), as `RelativeDate` in PHP. */
const MAX_COUNT = { d: 3660, w: 522, m: 120, y: 10 } as const;

const ROLLING = /^([+-])(\d{1,6})([dwmy])$/;

/**
 * The token in its canonical form (`-07D` → `-7d`, N clamped), or `null` when
 * it is not a relative date: the same rules as the server.
 */
export function normalizeRelativeDate(value: string): string | null {
    const token = value.trim().toLowerCase();

    if (
        Object.hasOwn(DAY_MESSAGES, token) ||
        Object.hasOwn(PERIOD_MESSAGES, token)
    ) {
        return token;
    }

    const match = ROLLING.exec(token);

    if (!match) return null;

    const [, sign, count, unit] = match as unknown as [
        string,
        '+' | '-',
        string,
        keyof typeof MAX_COUNT,
    ];

    return `${sign}${Math.max(1, Math.min(MAX_COUNT[unit], Number(count)))}${unit}`;
}

/**
 * Text of a token: the name of a period (`This month`) or its count
 * (`Past 45 days`). Weeks are told in days (`-2w` = `Past 14 days`, the same
 * range) and one day is today. Months and years use the `singular|plural`
 * text. An unknown token is shown as written.
 */
export function getRelativeDateLabel(
    value: string,
    message: (
        key: DataTableMessageKey,
        replacements?: Record<string, string | number>,
    ) => string,
): string {
    const token = normalizeRelativeDate(value);

    if (token === null) return value;

    const named = DAY_MESSAGES[token] ?? PERIOD_MESSAGES[token];

    if (named) return message(named);

    const [, sign, count, unit] = ROLLING.exec(token) as unknown as [
        string,
        '+' | '-',
        string,
        keyof typeof MAX_COUNT,
    ];
    const past = sign === '-';
    let amount = Number(count);

    if (unit === 'd' || unit === 'w') {
        amount *= unit === 'w' ? 7 : 1;

        if (amount === 1) return message('relative_today');

        return message(past ? 'relative_past_days' : 'relative_next_days', {
            count: amount,
        });
    }

    const key: DataTableMessageKey =
        unit === 'm'
            ? past
                ? 'relative_past_months'
                : 'relative_next_months'
            : past
              ? 'relative_past_years'
              : 'relative_next_years';
    const [singular = '', plural = singular] = message(key, {
        count: amount,
    }).split('|');

    return amount === 1 ? singular : plural;
}

const DAY = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The days of a `rel` filter as the server resolved them (`9–15 nov 2026`),
 * or `''` without them. They are calendar days: formatted in UTC, so the
 * server render and the browser show the same text.
 */
export function formatRelativeDateRange(
    range: readonly [string, string] | undefined,
    locale?: string,
): string {
    const [start, end] = (range ?? []).map((day) => {
        const match = DAY.exec(day);

        return match
            ? new Date(
                  Date.UTC(
                      Number(match[1]),
                      Number(match[2]) - 1,
                      Number(match[3]),
                  ),
              )
            : undefined;
    });

    if (!start || !end) return '';

    try {
        return new Intl.DateTimeFormat(locale, {
            day: 'numeric',
            month: 'short',
            year: 'numeric',
            timeZone: 'UTC',
        }).formatRange(start, end);
    } catch {
        return `${range?.[0]} – ${range?.[1]}`;
    }
}

/**
 * The only file of `lib/` that knows the UI framework: the `lib/data-table-*`
 * files import TanStack Table and the framework types from here, so React and
 * Vue share them and each one installs its own copy of this file.
 */
import type { Component, CSSProperties } from 'vue';

import type { TableFeature } from '@tanstack/vue-table';

import type { ColumnFilterItem } from '@/lib/data-table-types';

export * from '@tanstack/vue-table';

/** An icon component: `meta.icon`, `meta.icons` and the options' `icon`. */
export type DataTableIcon = Component;

/** Inline styles of a header or a cell (the column size). */
export type DataTableStyle = CSSProperties;

declare module '@tanstack/vue-table' {
    interface Plugins {
        dataTableFilteringFeature: TableFeature;
    }

    interface ColumnFilter extends Partial<
        Pick<ColumnFilterItem, 'operator' | 'variant' | 'filterId' | 'range'>
    > {}
}

// Copyright (c) 2024 Sadman Sakib. SPDX-License-Identifier: MIT

import {
    assignPrototypeAPIs,
    assignTableAPIs,
    type Column,
    type ColumnFilter,
    columnFilteringFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    functionalUpdate,
    metaHelper,
    type RowData,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    setStateSlice,
    type Table,
    type TableFeature,
    tableFeatures,
    type Updater,
    globalFilteringFeature,
} from '@/lib/data-table-tanstack';

import type {
    DataTableColumnMeta,
    DataTableTableMeta,
} from '@/lib/data-table-types';

import {
    getIsPlainFilter,
    getPlainFilterValue,
    normalizeColumnFilter,
    toPlainFilter,
} from '@/lib/data-table-filter-values';

type DataTableInstance = Table<DataTableFeatures, RowData>;

/**
 * The table filters on the server (`manualFiltering`): this feature only keeps
 * its filters in the URL format. A column has one "plain" filter, the value its
 * filter component edits (`column.getFilterValue()`), and, with `empty: true`
 * in PHP, an `is.empty` filter next to it for the rows without a value.
 */
const dataTableFilteringFeature: TableFeature = {
    getDefaultColumnDef: () => ({
        enableColumnFilter: false,
    }),
    assignColumnPrototype: (prototype, table) => {
        const instance = asDataTable(table);

        assignPrototypeAPIs('dataTableFilteringFeature', prototype, table, {
            column_getFilterValue: {
                fn: (column: { id: string }) =>
                    getPlainFilter(
                        instance,
                        column.id,
                        instance.atoms.columnFilters.get(),
                    ).value,
                memoDeps: () => [instance.atoms.columnFilters.get()],
            },
            column_setFilterValue: {
                fn: (column: { id: string }, updater: Updater<unknown>) =>
                    setPlainFilter(instance, column.id, updater),
            },
        });
    },
    constructTableAPIs: (table) => {
        assignTableAPIs('dataTableFilteringFeature', table, {
            table_setColumnFilters: {
                fn: (updater: Updater<ColumnFilter[]>) =>
                    setStateSlice(
                        table,
                        'columnFilters',
                        (old: ColumnFilter[]) =>
                            functionalUpdate(updater, old).filter(
                                (filter) => !getShouldRemoveFilter(filter),
                            ),
                    ),
            },
        });
    },
};

/**
 * Feature hooks get a `Table` generic over any features. This feature is only
 * registered in `dataTableFeatures`, so its hooks can use that table's types.
 */
function asDataTable(table: object) {
    return table as DataTableInstance;
}

/**
 * The filter of the column that its toolbar piece reads and writes: the plain
 * one, or else the first one that stands for a plain one (`toPlainFilter`), so
 * a `Status is Draft` row of the filter list still shows in the toolbar and
 * picking another option there replaces it instead of adding a second filter.
 */
function getPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    filters: ColumnFilter[],
) {
    const variant =
        instance.getColumn(columnId)?.columnDef.meta?.filterVariant ?? 'text';
    const items = filters.map((filter) =>
        filter.id === columnId ? normalizeColumnFilter(filter, variant) : null,
    );
    let index = items.findIndex(
        (item) => item !== null && getIsPlainFilter(item),
    );

    if (index === -1) {
        index = items.findIndex(
            (item) => item !== null && toPlainFilter(item) !== null,
        );
    }

    const item = items[index];
    const plain = item ? toPlainFilter(item) : null;
    const filter = filters[index];
    const value = plain ? getPlainFilterValue(plain) : undefined;

    return { index, filter, value };
}

function setPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    updater: Updater<unknown>,
) {
    instance.setColumnFilters((old) => {
        const {
            index,
            filter: previous,
            value: previousValue,
        } = getPlainFilter(instance, columnId, old);
        const value = functionalUpdate(updater, previousValue);
        const next: ColumnFilter = previous?.filterId
            ? { id: columnId, value, filterId: previous.filterId }
            : { id: columnId, value };

        if (index === -1) return [...old, next];
        return old.map((filter, filterIndex) =>
            filterIndex === index ? next : filter,
        );
    });
}

/**
 * Only an `undefined` value removes a filter: a cleared filter that keeps an
 * empty value (`''`, `[]`) is sent as no filter, and the `is.empty` filter,
 * whose value is `''`, must survive TanStack's default removal of empty text.
 */
function getShouldRemoveFilter(filter: ColumnFilter) {
    return filter.value === undefined;
}

export const dataTableFeatures = tableFeatures({
    columnFilteringFeature,
    globalFilteringFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    dataTableFilteringFeature,
    columnMeta: metaHelper<DataTableColumnMeta>(),
    tableMeta: metaHelper<DataTableTableMeta>(),
});

export type DataTableFeatures = typeof dataTableFeatures;

type DataTableColumn<TData extends RowData, TValue> = Column<
    DataTableFeatures,
    TData,
    TValue
>;

function isEmptyFilterOf(filter: ColumnFilter, columnId: string) {
    return filter.id === columnId && filter.operator === 'isEmpty';
}

/**
 * Whether the filter of the column also takes the rows without a value: an
 * `is.empty` filter next to its plain one, added with OR by the server
 * (`empty: true` in PHP).
 */
export function getEmptyFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
): boolean {
    return column.table.atoms.columnFilters
        .get()
        .some((filter) => isEmptyFilterOf(filter, column.id));
}

/** Adds or removes the rows without a value, keeping the picked values. */
export function setEmptyFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
    include: boolean,
) {
    const variant = column.columnDef.meta?.filterVariant ?? 'text';

    column.table.setColumnFilters((old) => {
        const rest = old.filter(
            (filter) => !isEmptyFilterOf(filter, column.id),
        );

        return include && variant
            ? [
                  ...rest,
                  {
                      id: column.id,
                      value: '',
                      variant,
                      operator: 'isEmpty',
                      filterId: `${column.id}-empty`,
                  },
              ]
            : rest;
    });
}

function isRelativeFilterOf(filter: ColumnFilter, columnId: string) {
    return filter.id === columnId && filter.operator === 'isRelativeToToday';
}

/**
 * The `rel` filter of a date column (days relative to today), with the days the
 * server resolved it to in `range`, or `undefined`.
 */
export function getRelativeFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
): ColumnFilter | undefined {
    return column.table.atoms.columnFilters
        .get()
        .find((filter) => isRelativeFilterOf(filter, column.id));
}

/**
 * Filters the column by days relative to today (`rel.<token>`), in place of its
 * plain filter and its other `rel` filters; `undefined` only removes them. The
 * `is.empty` filter of the column is kept.
 */
export function setRelativeFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
    token: string | undefined,
) {
    const variant = column.columnDef.meta?.filterVariant ?? 'date';

    column.table.setColumnFilters((old) => {
        const rest = old.filter(
            (filter) =>
                filter.id !== column.id ||
                (!isRelativeFilterOf(filter, column.id) &&
                    !getIsPlainFilter(normalizeColumnFilter(filter, variant))),
        );

        return token === undefined
            ? rest
            : [
                  ...rest,
                  {
                      id: column.id,
                      value: token,
                      variant,
                      operator: 'isRelativeToToday',
                      filterId: `${column.id}-rel`,
                  },
              ];
    });
}

/**
 * Filters of the column that its toolbar piece can not show (made in the
 * filter list, like `Name is mesa`), for its `+N` mark. Not counted: the one
 * the piece edits, the rows without a value when the column offers them
 * (`empty: true`) and the period relative to today of a date column.
 */
export function getHiddenFilterCount<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
): number {
    const meta = column.columnDef.meta;
    const variant = meta?.filterVariant;

    if (!variant) return 0;

    const filters = column.table.atoms.columnFilters.get();
    const { index } = getPlainFilter(
        asDataTable(column.table),
        column.id,
        filters,
    );
    const isDate = variant === 'date' || variant === 'date-range';

    return filters.filter(
        (filter, filterIndex) =>
            filter.id === column.id &&
            filterIndex !== index &&
            !(filter.operator === 'isEmpty' && meta?.empty) &&
            !(filter.operator === 'isRelativeToToday' && isDate),
    ).length;
}

/** Removes every filter of the column, the rows without a value included. */
export function clearColumnFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
) {
    column.table.setColumnFilters((old) =>
        old.filter((filter) => filter.id !== column.id),
    );
}

